```#[async_trait]
pub trait Operator {
    async fn init(&amp;self, context: Arc&lt;Context&gt;) -&gt; Result&lt;()&gt;;

    async fn exec&lt;S, R&gt;(
        &amp;self,
        sender: &amp;mut S,
        receiver: &amp;mut Pin&lt;&amp;mut R&gt;,
        context: Arc&lt;Context&gt;,
    ) -&gt; Result&lt;()&gt;
    where
        S: Sender&lt;Payload&gt; + Send,
        R: Receiver&lt;Payload&gt; + Send;
}

pub enum EnumOperator {
    Abort(crate::abort::Abort),
    Echo(crate::echo::Echo),
}

impl EnumOperator {
    async fn init(&amp;self, context: Arc&lt;Context&gt;) -&gt; Result&lt;()&gt; {
        match self {
            Self::Abort(abort) =&gt; abort.init(context).await,
            Self::Echo(echo) =&gt; echo.init(context).await,
        }
    }

    async fn exec&lt;S, R&gt;(
        &amp;self,
        sender: &amp;mut S,
        receiver: &amp;mut Pin&lt;&amp;mut R&gt;,
        context: Arc&lt;Context&gt;,
    ) -&gt; Result&lt;()&gt;
    where
        S: Sender&lt;Payload&gt; + Send,
        R: Receiver&lt;Payload&gt; + Send,
    {
        match self {
            Self::Abort(abort) =&gt; abort.exec(sender, receiver, context).await,
            Self::Echo(echo) =&gt; echo.exec(sender, receiver, context).await,
        }
    }
}```

```#[async_trait]
pub trait Operator&lt;'a, S, R&gt;: Sync
where
    S: Sender&lt;Payload&gt; + Send + 'a,
    R: Receiver&lt;Payload&gt; + Send + 'a,
{
    async fn init(&amp;self, context: Arc&lt;Context&gt;) -&gt; Result&lt;()&gt;
    where
        'a: 'async_trait;

    async fn exec(
        &amp;self,
        sender: &amp;mut S,
        receiver: &amp;mut Pin&lt;&amp;mut R&gt;,
        context: Arc&lt;Context&gt;,
    ) -&gt; Result&lt;()&gt;;
}```

```trait Formatter&lt;T, P&gt;
where
    P: Provider&lt;T&gt;,
{
    fn name(&amp;self) -&gt; String;
    fn format(&amp;self, p: P, msg: T) -&gt; String;
}```
上記のような trait があった時に `name` を利用しようとすると "type annotations need" と言われるのですが、書き方がわからないので誰かヘルプ...

